parameters.jsCode:
const input = $input.item.json;
const now = new Date();

const firstOfThisMonthUTC = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1);
const firstOfLastMonth = new Date(firstOfThisMonthUTC);
firstOfLastMonth.setUTCMonth(firstOfLastMonth.getUTCMonth() - 1);
const lastOfLastMonth = new Date(firstOfThisMonthUTC - 86400000);

function ymd(d) { return d.toISOString().slice(0, 10); }

const monthLabel = new Intl.DateTimeFormat('en-US', { month: 'long', year: 'numeric', timeZone: 'UTC' }).format(firstOfLastMonth);

return [{ json: {
  ...input,
  reportPeriodStart: ymd(firstOfLastMonth),
  reportPeriodEnd: ymd(lastOfLastMonth),
  monthLabel,
  reportingRegistrySheetId: 'REPLACE_WITH_REPORTING_REGISTRY_SHEET_ID',
  clientsTabName: 'Clients',
  driveRootFolderId: 'REPLACE_WITH_DRIVE_ROOT_FOLDER_ID',
  reportsFromEmail: 'reports@REPLACE_WITH_KEYSTONE_DOMAIN.com',
} }];

const items = $input.all();
const first = items[0].json;
const list = Array.isArray(first) ? first : [first];
const tenantId = list[0] ? list[0].tenantId : null;
const prior = $('Compute Report Period').item.json;
return [{ json: {
  ...prior,
  xeroTenantId: tenantId,
} }];

const resp = $input.item.json;
const prior = $('Extract Tenant ID + Reporting Config').item.json;
const values = resp.values || [];
const headers = values[0] || [];
const rows = values.slice(1).map(row => {
  const obj = {};
  headers.forEach((h, i) => { obj[h] = row[i] !== undefined ? row[i] : ''; });
  return obj;
});

function toBool(v) { return String(v).trim().toUpperCase() === 'TRUE'; }

const active = rows.filter(r => toBool(r.active));

return active.map(r => ({ json: {
  clientId: r.clientId,
  clientName: r.clientName,
  contactEmail: r.contactEmail,
  usesPhoneBooking: toBool(r.usesPhoneBooking),
  usesInvoiceAutomation: toBool(r.usesInvoiceAutomation),
  usesCollections: toBool(r.usesCollections),
  usesQuoting: toBool(r.usesQuoting),
  jobsSheetId: r.jobsSheetId || '',
  jobsSheetTabName: r.jobsSheetTabName || 'Jobs',
  reportingSheetId: r.reportingSheetId || '',
  callLogTabName: r.callLogTabName || 'CallLog',
  xeroTenantId: prior.xeroTenantId,
  driveRootFolderId: prior.driveRootFolderId,
  reportsFromEmail: prior.reportsFromEmail,
  monthLabel: prior.monthLabel,
  reportPeriodStart: prior.reportPeriodStart,
  reportPeriodEnd: prior.reportPeriodEnd,
  testMode: false,
} }));

const client = $input.item.json;

function inPeriod(dateStr) {
  if (!dateStr) return false;
  const d = String(dateStr).slice(0, 10);
  return d >= client.reportPeriodStart && d <= client.reportPeriodEnd;
}
function parseSheetRows(resp) {
  const values = resp.values || [];
  const headers = values[0] || [];
  return values.slice(1).map(row => {
    const obj = {};
    headers.forEach((h, i) => { obj[h] = row[i] !== undefined ? row[i] : ''; });
    return obj;
  });
}

let callsAnswered = 0;
let bookingsMade = 0;

if (client.usesPhoneBooking && client.reportingSheetId) {
  const resp = await this.helpers.httpRequestWithAuthentication.call(this, 'googleSheetsOAuth2Api', {
    method: 'GET',
    url: `https://sheets.googleapis.com/v4/spreadsheets/${client.reportingSheetId}/values/${client.callLogTabName}`,
    json: true,
  });
  const rows = parseSheetRows(resp);
  const thisMonth = rows.filter(r => inPeriod(r.timestamp));
  callsAnswered = thisMonth.length;
  bookingsMade = thisMonth.filter(r => String(r.bookingMade).toLowerCase() === 'true').length;
}

let invoicesSent = 0;
let cashJobs = 0;
let invoiceReferencesToCheck = [];

if (client.usesInvoiceAutomation && client.jobsSheetId) {
  const resp = await this.helpers.httpRequestWithAuthentication.call(this, 'googleSheetsOAuth2Api', {
    method: 'GET',
    url: `https://sheets.googleapis.com/v4/spreadsheets/${client.jobsSheetId}/values/${client.jobsSheetTabName}`,
    json: true,
  });
  const rows = parseSheetRows(resp);
  const invoicedThisMonth = rows.filter(r => String(r.status || '').trim() === 'Invoiced' && inPeriod(r.processedAt));
  const cashRows = invoicedThisMonth.filter(r => String(r.paymentMethod || '').trim() === 'Paid Cash');
  const sentRows = invoicedThisMonth.filter(r => String(r.paymentMethod || '').trim() !== 'Paid Cash');
  cashJobs = cashRows.length;
  invoicesSent = sentRows.length;
  invoiceReferencesToCheck = client.usesCollections ? sentRows.map(r => r.invoiceReference).filter(Boolean) : [];
}

return { json: {
  ...client,
  callsAnswered,
  bookingsMade,
  quotesGiven: 0,
  invoicesSent,
  cashJobs,
  invoiceReferencesToCheck,
} };

const client = $input.item.json;

let invoicesChased = 0;
let invoicesPaid = 0;

if (client.usesCollections && Array.isArray(client.invoiceReferencesToCheck) && client.invoiceReferencesToCheck.length) {
  for (const ref of client.invoiceReferencesToCheck) {
    try {
      const invResp = await this.helpers.httpRequestWithAuthentication.call(this, 'xeroOAuth2Api', {
        method: 'GET',
        url: 'https://api.xero.com/api.xro/2.0/Invoices',
        qs: { where: `Reference=="${ref}"` },
        headers: { 'xero-tenant-id': client.xeroTenantId, 'Accept': 'application/json' },
        json: true,
      });
      const invoice = (invResp.Invoices || [])[0];
      if (!invoice) continue;

      const histResp = await this.helpers.httpRequestWithAuthentication.call(this, 'xeroOAuth2Api', {
        method: 'GET',
        url: `https://api.xero.com/api.xro/2.0/Invoices/${invoice.InvoiceID}/History`,
        headers: { 'xero-tenant-id': client.xeroTenantId, 'Accept': 'application/json' },
        json: true,
      });
      const records = histResp.HistoryRecords || [];
      const wasChased = records.some(r => /COLLECTIONS_STAGE=\d/.test(String(r.Details || '')));
      if (wasChased) {
        invoicesChased += 1;
        if (Number(invoice.AmountDue) === 0) invoicesPaid += 1;
      }
    } catch (err) {
      // One invoice failing to fetch shouldn't break this client's whole report - skip and continue.
    }
  }
}

const { invoiceReferencesToCheck, ...rest } = client;
return { json: { ...rest, invoicesChased, invoicesPaid } };

const c = $input.item.json;

function plural(n, s) { return n === 1 ? s : s + 's'; }

const parts = [];

if (c.usesPhoneBooking) {
  if (c.callsAnswered > 0) {
    parts.push(`This month, we answered ${c.callsAnswered} ${plural(c.callsAnswered, 'call')} on your behalf, resulting in ${c.bookingsMade} booked ${plural(c.bookingsMade, 'job')}.`);
  } else {
    parts.push(`We didn't receive any calls on your behalf this month.`);
  }
  if (c.usesQuoting) {
    if (c.quotesGiven > 0) {
      parts.push(`We also provided ${c.quotesGiven} ${plural(c.quotesGiven, 'quote')} over the phone.`);
    } else {
      parts.push(`We didn't provide any phone quotes this month.`);
    }
  }
}

if (c.usesInvoiceAutomation) {
  if (c.invoicesSent > 0) {
    parts.push(`We sent ${c.invoicesSent} ${plural(c.invoicesSent, 'invoice')} this month.`);
  } else {
    parts.push(`We didn't send any invoices this month.`);
  }
  if (c.usesCollections) {
    if (c.invoicesChased > 0) {
      parts.push(`Of those, ${c.invoicesChased} needed a collections follow-up, and we successfully chased ${c.invoicesPaid} of them to full payment.`);
    } else {
      parts.push(`None of your invoices needed a collections follow-up this month.`);
    }
  }
  if (c.cashJobs > 0) {
    parts.push(`Separately, ${c.cashJobs} ${plural(c.cashJobs, 'job')} ${c.cashJobs === 1 ? 'was' : 'were'} paid in cash and logged directly.`);
  }
}

const bodyIntro = `Here's your Keystone performance summary for ${c.monthLabel}.`;
const bodyMiddle = parts.length ? parts.join(' ') : `We didn't have any activity to report for you this month.`;
const bodyOutro = `If you have any questions about this report, just get in touch.\n\nThanks for being a Keystone client.`;

const reportBodyText = `Hi ${c.clientName} team,\n\n${bodyIntro}\n\n${bodyMiddle}\n\n${bodyOutro}`;
const reportSubject = `Your Keystone Performance Report \u2014 ${c.monthLabel}`;

return { json: { ...c, reportSubject, reportBodyText } };

const resp = $input.item.json;
const prior = $('Has Contact Email?').item.json;
return { json: { ...prior, emailSent: true, emailMessageId: resp.id || null } };

const resp = $input.item.json;
const files = resp.files || [];
return { json: { ...$('Report Email Handled').item.json, existingFolderId: files.length ? files[0].id : null } };

const resp = $input.item.json;
const prior = $('Folder Resolved').item.json;
return { json: { ...prior, reportFileId: resp.id } };

parameters.body:
={{ `=== INTERNAL REFERENCE (not sent to client) ===
Client: ${$json.clientName} (${$json.clientId})
Period: ${$json.monthLabel} (${$json.reportPeriodStart} to ${$json.reportPeriodEnd})
Calls answered: ${$json.callsAnswered} | Bookings made: ${$json.bookingsMade} | Quotes given: ${$json.quotesGiven}
Invoices sent: ${$json.invoicesSent} | Chased: ${$json.invoicesChased} | Paid via chase: ${$json.invoicesPaid} | Cash jobs: ${$json.cashJobs}
Report emailed to: ${$json.contactEmail || '(none on file)'} | Email sent: ${$json.emailSent}

=== CLIENT-FACING REPORT (as sent) ===
Subject: ${$json.reportSubject}

${$json.reportBodyText}` }}
